import {officialThemes,shortcuts,REPO,themeFile,parseThemeFile,issueTheme,issueUrl} from './themes.mjs';
const $=s=>document.querySelector(s);
const node=(tag,className,text)=>{const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=text;return el;};
let filter='all',community=[],page=1,more=false,communityLoaded=false,communityError='',loading=false,currentTheme=null;
const menu=$('.menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');$('#navigation').classList.toggle('open',open);});
document.querySelectorAll('#navigation a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','메뉴 열기');$('#navigation').classList.remove('open');}));
const features={compose:{number:'01—',title:'머릿속 멜로디를\n눈앞의 노트로.',description:'피아노 롤에서 노트를 그리고, 마스터 키보드로 직접 연주하세요. 코드 구성음과 장르별 코드 진행이 첫 곡의 출발을 도와줍니다.',tags:['피아노 롤','코드 도우미','Oxygen Pro']},record:{number:'02—',title:'가장 좋은 순간을\n그대로 담으세요.',description:'MIDI와 오디오를 녹음하고, 루프 테이크에서 마음에 드는 구간을 골라보세요. 워프 마커와 타이밍 편집으로 연주의 흐름을 다듬을 수 있습니다.',tags:['루프 테이크','컴핑','워프 & 타이밍']},mix:{number:'03—',title:'당신의 소리에\n깊이를 더하세요.',description:'VST3 악기와 이펙트를 연결하고, 그룹·리턴·센드로 믹스를 구성하세요. 플러그인 오토메이션과 지연 보정으로 곡의 움직임을 완성합니다.',tags:['VST3','오토메이션','그룹 & 리턴']}};
document.querySelectorAll('[data-feature]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-feature]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});const t=features[button.dataset.feature];$('#feature-number').textContent=t.number;$('#feature-title').replaceChildren(...t.title.split('\n').flatMap((s,i)=>i?[document.createElement('br'),document.createTextNode(s)]:[document.createTextNode(s)]));$('#feature-description').textContent=t.description;$('#feature-tags').replaceChildren(...t.tags.map(s=>node('span','',s)));}));
function art(t,index,interactive=true){const el=node(interactive?'button':'div',`theme-art ${t.category}`);if(interactive){el.type='button';el.setAttribute('aria-label',`${t.name} 테마 색상 미리보기`);el.addEventListener('click',()=>openTheme(t));}el.style.setProperty('--start',t.start);el.style.setProperty('--end',t.mode===2?t.end:t.start);el.style.setProperty('--accent',t.accent);el.style.setProperty('--preview-text',t.category==='light'?'#23252a':'#eef2e7');el.style.setProperty('--angle',[180,90,135,225][t.direction]+'deg');el.append(node('span','theme-art-number',`${t.source==='community'?'COMMUNITY':'MIDISTUDIO COLLECTION'} / ${String(index+1).padStart(2,'0')}`));const mini=node('span','theme-mini');for(let i=0;i<4;i++){const row=node('span','mini-row');row.append(node('i'));mini.append(row);}el.append(mini,node('span','theme-art-title',t.name.toUpperCase()),node('span','theme-art-open','↗'));return el;}
function downloadTheme(t){if(t.source==='official'){const link=node('a');link.href=`themes/${t.id}.mptheme`;link.download=`MidiStudio-${t.id}.mptheme`;document.body.append(link);link.click();link.remove();return;}const blob=new Blob([themeFile(t)],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download=`MidiStudio-${t.id}.mptheme`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function openTheme(t){currentTheme=t;$('#dialog-preview').replaceChildren(art(t,Math.max(0,officialThemes.findIndex(s=>s.id===t.id)),false));$('#theme-dialog-title').textContent=t.name;$('#theme-dialog-description').textContent=t.description;$('#theme-discussion').hidden=!t.url;if(t.url)$('#theme-discussion').href=t.url;$('#theme-dialog').showModal();}
$('#dialog-download').addEventListener('click',()=>{if(currentTheme)downloadTheme(currentTheme);});
function renderThemes(){const query=$('#theme-search').value.trim().toLocaleLowerCase();let list=filter==='community'?community:officialThemes;list=list.filter(t=>(filter==='all'||filter==='community'||(filter==='gradient'?t.gradient:t.category===filter))&&`${t.name} ${t.description} ${t.author}`.toLocaleLowerCase().includes(query));$('#theme-grid').replaceChildren(...list.map((t,index)=>{const card=node('article','theme-card');card.append(art(t,index));const heading=node('div','theme-card-heading');heading.append(node('h3','',t.name));const download=node('button','theme-download','↓');download.type='button';download.setAttribute('aria-label',`${t.name} 테마 다운로드`);download.title='테마 다운로드';download.addEventListener('click',()=>downloadTheme(t));heading.append(download);const meta=node('div','theme-card-meta');meta.append(node('span','',t.category==='light'?'LIGHT':'DARK'));if(t.gradient)meta.append(node('span','','GRADIENT'));meta.append(node('span','theme-author',`by ${t.author}`));card.append(heading,node('p','',t.description),meta);return card;}));if(!list.length)$('#theme-grid').append(node('p','theme-empty',loading?'커뮤니티 테마를 불러오는 중입니다.':communityError&&filter==='community'?'GitHub 연결을 확인한 뒤 새로고침해 주세요.':filter==='community'&&!query?'아직 공유된 테마가 없어요. 첫 번째 색을 공유해보세요.':'검색 결과가 없습니다. 다른 이름으로 찾아보세요.'));$('#theme-status').textContent=filter==='community'?(loading?'GitHub 커뮤니티를 불러오는 중…':communityError||`불러온 커뮤니티 테마 ${community.length}개 중 ${list.length}개 표시 · 색상 설정만 공유됩니다.`):`공식 테마 ${list.length}개 · MidiStudio 2.0 호환 · 색상 조합 미리보기`;$('#community-actions').hidden=filter!=='community';$('#more-community').hidden=!more;$('#retry-community').disabled=loading;$('#more-community').disabled=loading;}
async function loadCommunity(reset=false){if(loading)return;loading=true;communityError='';if(reset){page=1;community=[];}renderThemes();try{const response=await fetch(`https://api.github.com/repos/${REPO}/issues?labels=theme&state=open&per_page=24&page=${page}`,{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(12000),credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw new Error(response.status===403||response.status===429?'GitHub 요청 한도에 도달했습니다. 잠시 후 다시 시도하거나 GitHub 게시판을 이용하세요.':'GitHub에서 목록을 가져오지 못했습니다.');const data=await response.json();if(!Array.isArray(data))throw new Error('테마 목록의 형식이 올바르지 않습니다.');const existing=new Set(community.map(t=>t.id));for(const issue of data){const t=issueTheme(issue);if(t&&!existing.has(t.id)){community.push(t);existing.add(t.id);}}more=!!response.headers.get('link')?.includes('rel="next"');page++;communityLoaded=true;}catch(error){communityError=error.name==='TimeoutError'?'연결 시간이 초과됐습니다. 새로고침하거나 GitHub 게시판을 이용하세요.':error.message||'네트워크 연결을 확인하세요.';}finally{loading=false;renderThemes();}}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});if(filter==='community'&&!communityLoaded&&!loading)void loadCommunity();renderThemes();}));$('#theme-search').addEventListener('input',renderThemes);$('#retry-community').addEventListener('click',()=>loadCommunity(true));$('#more-community').addEventListener('click',()=>loadCommunity());
function renderShortcuts(){const q=$('#shortcut-search').value.trim().toLocaleLowerCase();const rows=shortcuts.filter(s=>`${s.name} ${s.keys.join(' ')} ${s.category}`.toLocaleLowerCase().includes(q));$('#shortcut-list').replaceChildren(...rows.map(s=>{const row=node('div','shortcut-row');const label=node('span','',s.name);label.append(node('small','',s.category));const keys=node('span','shortcut-keys');s.keys.forEach((k,i)=>{if(i)keys.append(node('span','','+'));keys.append(node('kbd','',k));});row.append(label,keys);return row;}));if(!rows.length)$('#shortcut-list').append(node('p','theme-empty','일치하는 단축키가 없습니다.'));}$('#shortcut-search').addEventListener('input',renderShortcuts);
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',event=>{if(event.target===d){const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)d.close();}});});
$('#share-theme').addEventListener('click',()=>$('#share-dialog').showModal());$('#privacy-button').addEventListener('click',()=>$('#privacy-dialog').showModal());
$('#share-form').addEventListener('submit',async event=>{event.preventDefault();const status=$('#share-status'),file=$('#share-file').files[0],button=$('#share-form button[type=submit]');button.disabled=true;try{if(!file||!file.name.toLowerCase().endsWith('.mptheme')||file.size>5*1024*1024)throw new Error('5MB 이하의 .mptheme 파일을 선택하세요.');if(!$('#share-consent').checked)throw new Error('공개 공유에 동의해 주세요.');const theme=parseThemeFile(await file.text(),$('#share-name').value,$('#share-description').value);const link=node('a','text-link','GitHub 작성 화면 열기 ↗');link.href=issueUrl(theme);link.target='_blank';link.rel='noopener noreferrer';status.replaceChildren(document.createTextNode('색상 설정을 추출했습니다. 다음 링크에서 내용을 확인하고 게시하세요. '),link);}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
$('#copy-checksum').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#checksum').value);$('#copy-status').textContent='SHA-256을 복사했습니다.';}catch{$('#checksum').select();$('#copy-status').textContent='위 값을 선택했습니다. Ctrl+C로 복사하세요.';}});
fetch('release.json').then(r=>{if(!r.ok)throw new Error('metadata');return r.json();}).then(r=>{$('#checksum').value=r.installer.sha256;$('#installer-meta').textContent=`Windows 10 / 11 · 64-bit · ${(r.installer.bytes/1048576).toFixed(1)} MB`;}).catch(()=>{$('#copy-status').textContent='파일 정보는 GitHub 릴리스의 SHA256SUMS.txt에서 확인하세요.';$('#copy-checksum').disabled=true;});
$('#year').textContent=new Date().getFullYear();renderThemes();renderShortcuts();
